<?php
declare(strict_types=1);
require_once '../conexao.php';
require_once '../helpers/auth.php';
require_once '../helpers/seguranca.php';
$admin=exigirLoginAdmin();

$stmtTotais=$pdo->query("SELECT status,COUNT(*) total FROM pedidos_exames GROUP BY status");
$totais=[];while($r=$stmtTotais->fetch())$totais[$r['status']]=(int)$r['total'];
foreach(['aguardando_analise','aguardando_nova_analise','em_espera','aguardando_vaga','agendado','finalizado','cancelado'] as $st)$totais[$st]=$totais[$st]??0;

$where=[];$params=[];
if(!empty($_GET['busca'])){ $b='%'.trim($_GET['busca']).'%';$where[]='(pac.nome LIKE ? OR pac.cpf LIKE ? OR pac.cns LIKE ? OR p.protocolo LIKE ?)';array_push($params,$b,$b,$b,$b); }
if(!empty($_GET['status'])){$where[]='p.status=?';$params[]=$_GET['status'];}
if(!empty($_GET['unidade_id'])){$where[]='p.unidade_id=?';$params[]=(int)$_GET['unidade_id'];}
if(!empty($_GET['especialidade_id'])){$where[]='e.especialidade_id=?';$params[]=(int)$_GET['especialidade_id'];}
if(!empty($_GET['exame_id'])){$where[]='p.exame_id=?';$params[]=(int)$_GET['exame_id'];}

$fromSql=" FROM pedidos_exames p INNER JOIN pacientes pac ON pac.id=p.paciente_id INNER JOIN exames e ON e.id=p.exame_id INNER JOIN especialidades esp ON esp.id=e.especialidade_id INNER JOIN unidades u ON u.id=p.unidade_id";
$whereSql=$where?' WHERE '.implode(' AND ',$where):'';
$stmtContagem=$pdo->prepare('SELECT COUNT(*)'.$fromSql.$whereSql);$stmtContagem->execute($params);$totalPedidosFiltrados=(int)$stmtContagem->fetchColumn();
$porPagina=50;$totalPaginas=max(1,(int)ceil($totalPedidosFiltrados/$porPagina));
$paginaSolicitada=filter_var($_GET['pagina']??1,FILTER_VALIDATE_INT);$pagina=max(1,min((int)($paginaSolicitada?:1),$totalPaginas));
$offset=($pagina-1)*$porPagina;$primeiroResultado=$totalPedidosFiltrados?$offset+1:0;$ultimoResultado=min($offset+$porPagina,$totalPedidosFiltrados);
$sql="SELECT p.*,pac.id pac_id,pac.nome paciente_nome,pac.cpf,pac.cns,pac.telefone,e.nome exame_nome,e.tipo exame_tipo,esp.nome especialidade_nome,u.nome unidade_nome".$fromSql.$whereSql;
$sql.=" ORDER BY CASE WHEN p.status='aguardando_vaga' THEN 0 ELSE 1 END,p.emergencia DESC,p.prioridade ASC,p.data_entrada_fila ASC,p.criado_em DESC LIMIT {$porPagina} OFFSET {$offset}";
$stmt=$pdo->prepare($sql);$stmt->execute($params);$pedidos=$stmt->fetchAll();
$queryAnterior=$_GET;$queryAnterior['pagina']=max(1,$pagina-1);$queryProxima=$_GET;$queryProxima['pagina']=min($totalPaginas,$pagina+1);

$especialidades=$pdo->query("SELECT id,nome,ativo FROM especialidades ORDER BY ativo DESC,nome")->fetchAll();
$exames=$pdo->query("SELECT id,nome,especialidade_id,unidade_id,ativo FROM exames ORDER BY ativo DESC,nome")->fetchAll();
$unidades=$pdo->query("SELECT id,nome,ativo FROM unidades ORDER BY ativo DESC,nome")->fetchAll();
$especialidadesInativas=array_values(array_map('intval',array_column(array_filter($especialidades,fn($item)=>!(int)$item['ativo']),'id')));
$examesInativos=array_values(array_map('intval',array_column(array_filter($exames,fn($item)=>!(int)$item['ativo']),'id')));
$unidadesInativas=array_values(array_map('intval',array_column(array_filter($unidades,fn($item)=>!(int)$item['ativo']),'id')));
$novas=(int)$pdo->query("SELECT COUNT(*) FROM notificacoes_admin WHERE lida=0")->fetchColumn();
?>
<!doctype html><html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gestão de Pedidos</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../css/exames.css" rel="stylesheet"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><style>body{font-family:Arial,sans-serif;background:#f4f6f8;padding:20px}.resumo{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-bottom:20px}.resumo-box{padding:12px;border-radius:10px;font-weight:bold;text-align:center;background:#fff;border:1px solid #dfe4ea}.resumo-box span{display:block;font-size:24px;margin-top:4px}.filtro-card{background:#fff;padding:16px;border-radius:10px;border:1px solid #dfe4ea;margin-bottom:20px}</style></head><body>
<div class="d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2"><div><h2 class="fw-bold text-primary mb-0">Gestão de Pedidos e Pacientes</h2><small class="text-muted">Operador: <?=htmlspecialchars($admin['nome'])?> (<?=ucfirst($admin['perfil'])?>)</small></div><div><a href="dashboard.php" class="btn btn-outline-primary btn-sm me-1">Dashboard</a><a href="pendencias.php" class="btn btn-warning btn-sm me-1"><i class="fa-solid fa-clock"></i> Pendências<?php if($novas): ?> <span class="badge bg-danger"><?=$novas?></span><?php endif; ?></a><a href="../logout.php" class="btn btn-outline-danger btn-sm">Sair</a></div></div>
<div class="resumo"><div class="resumo-box">Aguardando Análise<span><?=$totais['aguardando_analise']?></span></div><div class="resumo-box">Nova Análise<span><?=$totais['aguardando_nova_analise']?></span></div><div class="resumo-box">Em Espera<span><?=$totais['em_espera']?></span></div><div class="resumo-box">Aguardando Vaga<span><?=$totais['aguardando_vaga']?></span></div><div class="resumo-box">Agendados<span><?=$totais['agendado']?></span></div><div class="resumo-box">Finalizados<span><?=$totais['finalizado']?></span></div></div>
<div class="filtro-card"><form method="GET" class="row g-2"><div class="col-md-4"><input name="busca" class="form-control" placeholder="Nome, CPF, CNS ou protocolo" value="<?=htmlspecialchars($_GET['busca']??'')?>"></div><div class="col-md-2"><select name="status" class="form-select"><option value="">Todos os Status</option><?php foreach(['aguardando_analise'=>'Aguardando Análise','aguardando_nova_analise'=>'Nova Análise','em_espera'=>'Em Espera','aguardando_vaga'=>'Aguardando Vaga','agendado'=>'Agendado','finalizado'=>'Finalizado','cancelado'=>'Cancelado'] as $v=>$label): ?><option value="<?=$v?>" <?=($_GET['status']??'')===$v?'selected':''?>><?=$label?></option><?php endforeach; ?></select></div><div class="col-md-2"><select name="especialidade_id" id="especialidade_id" class="form-select"><option value="">Todas as Especialidades</option><?php foreach($especialidades as $e): ?><option value="<?=$e['id']?>" <?=((string)($_GET['especialidade_id']??''))===(string)$e['id']?'selected':''?>><?=htmlspecialchars($e['nome'])?></option><?php endforeach; ?></select></div><div class="col-md-2"><select name="exame_id" id="exame_id" class="form-select"><option value="">Todos os Exames/Consultas</option><?php foreach($exames as $e): ?><option value="<?=$e['id']?>" data-especialidade="<?=$e['especialidade_id']?>" <?=((string)($_GET['exame_id']??''))===(string)$e['id']?'selected':''?>><?=htmlspecialchars($e['nome'])?></option><?php endforeach; ?></select></div><div class="col-md-1"><select name="unidade_id" class="form-select"><option value="">Unidade</option><?php foreach($unidades as $u): ?><option value="<?=$u['id']?>" <?=((string)($_GET['unidade_id']??''))===(string)$u['id']?'selected':''?>><?=htmlspecialchars($u['nome'])?></option><?php endforeach; ?></select></div><div class="col-md-1 d-grid"><button class="btn btn-primary fw-bold">Filtrar</button></div><div class="col-12"><a href="listagem_ordens.php" class="btn btn-outline-secondary btn-sm">Limpar filtros</a></div></form></div>
<div class="card-box"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead class="table-light"><tr><th>Protocolo</th><th>Paciente</th><th>Procedimento</th><th>Especialidade</th><th>Status</th><th>Prioridade</th><th></th></tr></thead><tbody><?php if(!$pedidos): ?><tr><td colspan="7" class="text-center py-4 text-muted">Nenhum pedido encontrado.</td></tr><?php else: foreach($pedidos as $p): ?><tr><td class="fw-bold text-primary"><?=htmlspecialchars($p['protocolo'])?></td><td><a href="paciente_perfil.php?id=<?=$p['pac_id']?>" class="text-decoration-none fw-bold text-dark"><?=htmlspecialchars($p['paciente_nome'])?></a><br><small><?=formatarCPF($p['cpf'])?></small></td><td><?=htmlspecialchars($p['exame_nome'])?></td><td><?=htmlspecialchars($p['especialidade_nome'])?></td><td><span class="badge-status st-<?=htmlspecialchars($p['status'])?>"><?=ucwords(str_replace('_',' ',$p['status']))?></span><?php if($p['status']==='aguardando_nova_analise'): ?><span class="badge bg-primary ms-1">NOVO</span><?php endif; ?></td><td><?php if($p['emergencia']): ?><span class="badge bg-danger">Emergência</span><?php else: ?><span class="badge bg-light text-secondary border">Normal</span><?php endif; ?></td><td><a href="paciente_perfil.php?id=<?=$p['pac_id']?>" class="btn btn-primary btn-sm">Abrir Prontuário</a></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
<script>const esp=document.getElementById('especialidade_id'),ex=document.getElementById('exame_id');const especialidadesInativas=new Set(<?=json_encode($especialidadesInativas)?>),examesInativos=new Set(<?=json_encode($examesInativos)?>),unidadesInativas=new Set(<?=json_encode($unidadesInativas)?>);[...esp.options].forEach(o=>{if(especialidadesInativas.has(Number(o.value)))o.textContent+=' (Inativa)'});[...ex.options].forEach(o=>{if(examesInativos.has(Number(o.value)))o.textContent+=' (Inativo)'});const unidadeSelect=document.querySelector('select[name="unidade_id"]');[...unidadeSelect.options].forEach(o=>{if(unidadesInativas.has(Number(o.value)))o.textContent+=' (Inativa)'});function filtrarExames(){const v=esp.value;[...ex.options].forEach(o=>{if(!o.value)return;o.hidden=!!v&&o.dataset.especialidade!==v});if(ex.selectedOptions[0]?.hidden)ex.value=''}esp.addEventListener('change',filtrarExames);filtrarExames();</script>
<div class="d-flex justify-content-between align-items-center my-3 small text-muted"><span>Mostrando <?= $primeiroResultado ?>–<?= $ultimoResultado ?> de <?= $totalPedidosFiltrados ?> pedidos<?= $pagina > 1 ? ' (página ' . $pagina . ' de ' . $totalPaginas . ')' : '' ?></span><?php if ($totalPaginas > 1): ?><nav aria-label="Paginação de pedidos"><ul class="pagination pagination-sm mb-0"><li class="page-item <?= $pagina <= 1 ? 'disabled' : '' ?>"><a class="page-link" href="listagem_ordens.php?<?= htmlspecialchars(http_build_query($queryAnterior), ENT_QUOTES, 'UTF-8') ?>">Anterior</a></li><li class="page-item disabled"><span class="page-link"><?= $pagina ?> / <?= $totalPaginas ?></span></li><li class="page-item <?= $pagina >= $totalPaginas ? 'disabled' : '' ?>"><a class="page-link" href="listagem_ordens.php?<?= htmlspecialchars(http_build_query($queryProxima), ENT_QUOTES, 'UTF-8') ?>">Próxima</a></li></ul></nav><?php endif; ?></div>
</body></html>
